// Java NIO Selector 在 Linux 下底层是 epoll
Selector selector = Selector.open();                 // ≈ epoll_create
ServerSocketChannel server = ServerSocketChannel.open();
server.bind(new InetSocketAddress(8080));
server.configureBlocking(false);
server.register(selector, SelectionKey.OP_ACCEPT);   // ≈ epoll_ctl(ADD)

while (true) {
    selector.select();                               // ≈ epoll_wait，只返回就绪的
    Iterator<SelectionKey> it = selector.selectedKeys().iterator();
    while (it.hasNext()) {
        SelectionKey key = it.next(); it.remove();
        if (key.isAcceptable()) {
            SocketChannel ch = server.accept();
            ch.configureBlocking(false);
            ch.register(selector, SelectionKey.OP_READ);
        } else if (key.isReadable()) {
            ByteBuffer buf = ByteBuffer.allocate(1024);
            if (((SocketChannel) key.channel()).read(buf) < 0) key.cancel();
        }
    }
}
