// 自定义协议：| magic 2B | version 1B | length 4B | body |
public class ServerInit extends ChannelInitializer<SocketChannel> {
    @Override
    protected void initChannel(SocketChannel ch) {
        ch.pipeline()
          .addLast(new LengthFieldBasedFrameDecoder(
                  1024 * 1024,   // maxFrameLength，防止恶意超大帧
                  3,             // lengthFieldOffset：跳过 magic + version
                  4,             // lengthFieldLength
                  0,             // lengthAdjustment
                  0))            // initialBytesToStrip：保留头部交给后续解码
          .addLast(new MyProtocolDecoder())     // 校验 magic、解析 body
          .addLast(new MyProtocolEncoder())     // 写 magic、version、length、body
          .addLast(new BizHandler());
    }
}

