// Netty 主从 Reactor
EventLoopGroup boss = new NioEventLoopGroup(1);        // 主 Reactor：只处理 accept
EventLoopGroup worker = new NioEventLoopGroup();       // 从 Reactor：默认 CPU*2 个线程处理读写
EventExecutorGroup biz = new DefaultEventExecutorGroup(32);  // 业务线程池，执行阻塞逻辑

new ServerBootstrap()
    .group(boss, worker)
    .channel(NioServerSocketChannel.class)
    .childHandler(new ChannelInitializer<SocketChannel>() {
        @Override protected void initChannel(SocketChannel ch) {
            ch.pipeline()
              .addLast(new LengthFieldBasedFrameDecoder(1 << 20, 0, 4, 0, 4))
              .addLast(new RequestDecoder())                 // 在 IO 线程执行，很快
              .addLast(biz, new DbQueryHandler());           // 阻塞查询放到业务线程池
        }
    })
    .bind(8080).sync();
